function ss_id(string $name):?string{static $map=null;$map??=pp_read(__DIR__.'/../assets/seasons/team-map.json');return $map[trim($name)]??$map[pp_club_key(['name'=>trim($name)])]??null;}
function ss_attach(array $data,array $state,DateTimeImmutable $now):array{
 $lookup=[];foreach(array_merge(array_values($state['matches']??[]),array_values($state['predictions']??[]))as$m){$h=ss_id($m['home']['name']);$a=ss_id($m['away']['name']);if($h&&$a&&($m['competitionId']??'')===$data['competitionId']&&($m['season']??$data['season'])===$data['season'])$lookup[$h.'|'.$a][]=$m;}
