  if($p&&(!empty($p['weeklyPrepared'])||!empty($p['weeklyPublished'])||$released)){$score=$p['publishedScore']??$p['mostLikelyScore']??null;if($score){$m['forecast']=[(int)$score['home'],(int)$score['away']];$m['forecastPublishedAt']=$p['weeklyPreparedAt']??$p['createdAt']??null;$m['forecastSource']='shared-match-summary';$m['forecastReplayReleased']=$released;$m['forecastId']=$v['id'];}}
 }unset($m);return $data;
}
function ss_latest_snapshot(array $bundled,?array $cached):array{
 if(!$cached||($cached['competitionId']??'')!==($bundled['competitionId']??'')||($cached['season']??'')!==($bundled['season']??'')||count($cached['teams']??[])!==count($bundled['teams']??[])||count($cached['matches']??[])!==count($bundled['matches']??[]))return $bundled;
