function ss_get(string $id,array $cfg,DateTimeImmutable $now):array{
 $codes=['tr.1'=>'tur.1','en.1'=>'eng.1','es.1'=>'esp.1','de.1'=>'ger.1','it.1'=>'ita.1','fr.1'=>'fra.1','ucl'=>'uefa.champions','uel'=>'uefa.europa','uecl'=>'uefa.europa.conf'];if(!is_string($id)||!isset($codes[$id]))throw new RuntimeException('Geçersiz organizasyon');
 $bundled=pp_read(__DIR__.'/../assets/seasons/2026-27.json')[$id];$cache=$cfg['storage_dir'].'/season-'.$id.'.json';$saved=pp_read($cache);$data=ss_latest_snapshot($bundled,$saved['data']??null);$at=$data===$bundled?0:($saved['epoch']??0);$state=pp_read($cfg['storage_dir'].'/state.json');
 if($now->getTimestamp()-$at>=300){
  $lock=fopen($cache.'.lock','c');if($lock&&flock($lock,LOCK_EX|LOCK_NB)){try{
