   $candidate=$data;$month=$now->format('Ym');$url='https://site.api.espn.com/apis/site/v2/sports/soccer/'.$codes[$id].'/scoreboard?dates='.$month.'&limit=1000';$doc=pp_fetch($url,$cfg);$events=$doc['events']??null;if(!is_array($events)||count($events)>=1000)throw new RuntimeException('Eksik maç veri yanıtı');
