   $standingUrl='https://site.web.api.espn.com/apis/v2/sports/soccer/'.$codes[$id].'/standings?season=2026';$standing=pp_fetch($standingUrl,$cfg);$collect=function(array $node)use(&$collect):array{$all=$node['standings']['entries']??[];foreach($node['children']??[]as$child)$all=array_merge($all,$collect($child));return $all;};$rows=$collect($standing);if(count($rows)!==count($candidate['teams']))throw new RuntimeException('Puan tablosu takım sayısı uyuşmuyor');$base=[];$seen=[];
